
-- ==========================================
-- REEL NEWS DATABASE SCHEMA
-- PostgreSQL
-- ==========================================

-- 1. PUBLISHER
CREATE TABLE publisher (
    "publisherID" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, --Generates value if one is not provided, also sequentially increments
    name VARCHAR(255),
    location VARCHAR(255),
    "logoURL" TEXT,
    "landingPage" TEXT,
    "biasCategory" VARCHAR(20),
    "biasSource" TEXT
);

-- 2. AUTHOR
CREATE TABLE author (
    "authorID" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "firstName" VARCHAR(255),
    "lastName" VARCHAR(255)
);

-- 3. TAG
CREATE TABLE tag (
    "tagID" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name VARCHAR(50),
    description TEXT
);

-- 4. ARTICLE
CREATE TABLE article (
    "articleID" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    title VARCHAR(255),
    link TEXT,
    "dateAccessed" TIMESTAMP,
    "datePublished" TIMESTAMP,
    "lastChecked" TIMESTAMP,
    hash CHAR(64),
    "publisherID" INT REFERENCES publisher("publisherID"),
    "biasCategory" VARCHAR(20),
    "biasSource" TEXT,
    "aiBiasScore" FLOAT
);

-- 5. ARTICLE_AUTHOR
CREATE TABLE article_author (
    "articleID" INT REFERENCES article("articleID"),
    "authorID" INT REFERENCES author("authorID"),
    PRIMARY KEY ("articleID", "authorID")
);

-- 6. STORY
CREATE TABLE story (
    "storyID" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "currentRevisionNum" INT,
    "dateCreated" TIMESTAMP,
    "dateModified" TIMESTAMP,
    status VARCHAR(30)
);

-- 7. STORY_REVISION
CREATE TABLE story_revision (
    "storyID" INT REFERENCES story("storyID"),
    "revisionNum" INT,
    "dateCreated" TIMESTAMP,
    headline VARCHAR(255),
    summary TEXT,
    "changeNote" TEXT,
    PRIMARY KEY ("storyID", "revisionNum")
);

-- Add the composite foreign key from STORY to STORY_REVISION after both tables exist.
ALTER TABLE story
ADD CONSTRAINT fk_story_current_revision
FOREIGN KEY ("storyID", "currentRevisionNum")
REFERENCES story_revision ("storyID", "revisionNum");

-- 8. REVISION_ARTICLE
CREATE TABLE revision_article (
    "articleID" INT REFERENCES article("articleID"),
    "storyID" INT,
    "revisionNum" INT,
    "articleHash" CHAR(64),
    PRIMARY KEY ("articleID", "storyID", "revisionNum"),
    FOREIGN KEY ("storyID", "revisionNum")
    REFERENCES story_revision ("storyID", "revisionNum")
);

-- 9. STORY_TAG
CREATE TABLE story_tag (
    "storyID" INT REFERENCES story("storyID"),
    "tagID" INT REFERENCES tag("tagID"),
    PRIMARY KEY ("storyID", "tagID")
);

-- 10. ARTICLE_TAG
CREATE TABLE article_tag (
    "articleID" INT REFERENCES article("articleID"),
    "tagID" INT REFERENCES tag("tagID"),
    PRIMARY KEY ("articleID", "tagID")
);


--Checking if successful schema creation
SELECT *
FROM pg_tables
WHERE tableowner = 'reelnews_georgia';

